import { defineConfig } from 'vite';

// Build once, deploy everywhere: the CI builds a single artifact (`npm run build`)
// that is promoted to dev then prd. Nothing environment-specific may be baked in,
// so per-environment values (API URL, Firebase config) are read at runtime from
// /config.json, generated by the serverless Terraform stack.
// Only the in-browser mock is selected here: `vite` (dev server) uses it, every build uses the real services.
const DISCORD_CLIENT_ID = process.env.DISCORD_CLIENT_ID ?? '1562814087900037260';

export default defineConfig(({ mode }) => {
  const backend = process.env.BACKEND ?? (mode === 'development' ? 'mock' : 'gcp');
  return {
    define: {
      __APP_CONFIG__: JSON.stringify({ discordClientId: DISCORD_CLIENT_ID }),
      // Separate literal so `if (__BACKEND__ === 'mock')` is folded and the mock is tree-shaken from builds.
      __BACKEND__: JSON.stringify(backend),
    },
    build: { target: 'es2022', sourcemap: true },
    test: { environment: 'node' },
  };
});
